    full_reason = reason
    if extra:
        full_reason = extra[0]
    return {
        "openalex_id": oid,
        "title": title,
        "decision": decision,
        "hard_exclusion": hard_excl,
        "hard_exclusion_reason": hard_reason,
        "evidence_level": ev_level,
        "african_centrality": ac,
        "local_specificity": ls,
        "scientific_depth": sd,
        "knowledge_value": kv,
        "local_applicability": la,
        "total_score": ac+ls+sd+kv+la,
        "african_focus": af,
        "scientific_evidence": se,
        "african_country_codes": cc,
        "african_relevance_tags": tags,
        "evidence": evidence,
        "inference_basis": ib,
        "reason": full_reason,
        "field_name": fn,
        "primary_topic": pt,
        "work_type": wt
    }

